window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b45f6db05c393142"]={"versions": [{"id": "FIG-b45f6db05c393142", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- bzw. Modulinklusionsdiagramm der Header-Dateistruktur des AUTOSAR Classic BSW-Moduls <code>CanNm</code> (CAN Network Management) innerhalb des AUTOSAR-Kommunikationsstacks. Das Diagramm modelliert Dateieinheiten (C-Quelldatei und Header-Dateien) sowie deren gerichtete <code>#include</code>-Abhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Quellfile:</p>\n<ul class=\"fig-list\"><li><code>CanNm.c</code>: Kern-Implementierungsdatei des Moduls CanNm.\n</li></ul>\n<p class=\"fig-p\">Header-Dateien und Inklusionsbeziehungen (jeweils über gerichtete Pfeile dargestellt):</p>\n<ul class=\"fig-list\"><li><code>CanNm.c</code> inkludiert:\n<ul class=\"fig-list\"><li><code>CanNm.h</code> (Modul-Header)\n</li><li><code>CanNm_Cbk.h</code> (Callback-Deklarationen des CanNm)\n</li><li><code>Nm_Cbk.h</code> (Callback-Deklarationen des generischen NM-Koordinators)\n</li><li><code>Nm_Cfg.h</code> (Konfigurationsheader des generischen NM)\n</li><li><code>MemMap.h</code> (Speicher-Mapping-Makros)\n</li><li><code>Det.h</code> (Default Error Tracer)\n</li><li><code>SchM_CanNm.h</code> (BSW-Scheduler-/RTE-Header für CanNm)\n</li><li><code>PduR_CanNm.h</code> (Schnittstellen-Header zum PDU-Router)\n</li><li><code>CanIf.h</code> (Schnittstellen-Header zum CAN-Interface)\n</li></ul>\n</li><li><code>CanNm.h</code> inkludiert:\n<ul class=\"fig-list\"><li><code>CanNm_Cfg.h</code> (Modulspezifische Vorkompilierungs- und Konfigurationsparameter)\n</li><li><code>NmStack_Types.h</code> (Netzwerkmanagement-spezifische Basistypen)\n</li><li><code>ComStack_Types.h</code> (Kommunikationsstack-Basistypen)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Inklusions- und Kompilierzeit-Modell ohne Laufzeitdynamik. Die gerichteten Kanten definieren die Kompilierzeit-Abhängigkeiten (<code>#include</code>). <code>CanNm.c</code> importiert direkt sämtliche Modulschnittstellen (Unterbauschicht <code>CanIf</code>, Routing <code>PduR</code>, Diagnose/Fehler <code>Det</code>, Scheduler <code>SchM</code>, Callbacks sowie NM-Konfiguration und Memory-Mapping). <code>CanNm.h</code> propagiert die Typendefinitionen (<code>NmStack_Types.h</code>, <code>ComStack_Types.h</code>) sowie die eigene Konfiguration (<code>CanNm_Cfg.h</code>) an Verwender des Moduls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Vorgabe für die Modulstrukturierung und Header-Inklusionshierarchie der AUTOSAR-Spezifikation. Implementierungen des <code>CanNm</code>-Treibers müssen exakt diese Inklusionsbeziehungen einhalten, um zyklische Abhängigkeiten zu verhindern, die Typdeklarationen konsistent bereitzustellen und den BSW-Architekturrichtlinien bezüglich Speicherkartierung (<code>MemMap.h</code>), Fehlererfassung (<code>Det.h</code>) und Task-Scheduling (<code>SchM_CanNm.h</code>) zu entsprechen.</p>"}, {"id": "FIG-0efe2ddc2819f77b", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- bzw. Modulinklusionsdiagramm der Header-Dateistruktur des AUTOSAR Classic BSW-Moduls <code>CanNm</code> (CAN Network Management) innerhalb des AUTOSAR-Kommunikationsstacks. Das Diagramm modelliert Dateieinheiten (C-Quelldatei und Header-Dateien) sowie deren gerichtete <code>#include</code>-Abhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Quellfile:</p>\n<ul class=\"fig-list\"><li><code>CanNm.c</code>: Kern-Implementierungsdatei des Moduls CanNm.\n</li></ul>\n<p class=\"fig-p\">Header-Dateien und Inklusionsbeziehungen (jeweils über gerichtete Pfeile dargestellt):</p>\n<ul class=\"fig-list\"><li><code>CanNm.c</code> inkludiert:\n<ul class=\"fig-list\"><li><code>CanNm.h</code> (Modul-Header)\n</li><li><code>CanNm_Cbk.h</code> (Callback-Deklarationen des CanNm)\n</li><li><code>Nm_Cbk.h</code> (Callback-Deklarationen des generischen NM-Koordinators)\n</li><li><code>CanNm_MemMap.h</code> (Modulspezifische Speicher-Mapping-Makros)\n</li><li><code>Det.h</code> (Default Error Tracer)\n</li><li><code>SchM_CanNm.h</code> (BSW-Scheduler-/RTE-Header für CanNm)\n</li><li><code>PduR_CanNm.h</code> (Schnittstellen-Header zum PDU-Router)\n</li><li><code>CanIf.h</code> (Schnittstellen-Header zum CAN-Interface)\n</li></ul>\n</li><li><code>CanNm.h</code> inkludiert:\n<ul class=\"fig-list\"><li><code>CanNm_Cfg.h</code> (Modulspezifische Vorkompilierungs- und Konfigurationsparameter)\n</li><li><code>NmStack_Types.h</code> (Netzwerkmanagement-spezifische Basistypen)\n</li><li><code>ComStack_Types.h</code> (Kommunikationsstack-Basistypen)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Inklusions- und Kompilierzeit-Modell ohne Laufzeitdynamik. Die gerichteten Kanten definieren die Kompilierzeit-Abhängigkeiten (<code>#include</code>). <code>CanNm.c</code> importiert direkt die Modulschnittstellen (Unterbauschicht <code>CanIf</code>, Routing <code>PduR</code>, Fehlererfassung <code>Det</code>, Scheduler <code>SchM</code>, Callbacks sowie modulspezifisches Memory-Mapping <code>CanNm_MemMap.h</code>). <code>CanNm.h</code> propagiert die Typendefinitionen (<code>NmStack_Types.h</code>, <code>ComStack_Types.h</code>) sowie die eigene Konfiguration (<code>CanNm_Cfg.h</code>) an Verwender des Moduls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Vorgabe für die Modulstrukturierung und Header-Inklusionshierarchie der AUTOSAR-Spezifikation. Implementierungen des <code>CanNm</code>-Treibers müssen exakt diese Inklusionsbeziehungen einhalten, um zyklische Abhängigkeiten zu verhindern, die Typdeklarationen konsistent bereitzustellen und den BSW-Architekturrichtlinien bezüglich des modulspezifischen Speicherkartierungskonzepts (<code>CanNm_MemMap.h</code>), der Fehlererfassung (<code>Det.h</code>) und des Task-Schedulings (<code>SchM_CanNm.h</code>) zu entsprechen.</p>"}], "trans": [{"from": "FIG-b45f6db05c393142", "to": "FIG-0efe2ddc2819f77b", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Header-Inklusion <code>Nm_Cfg.h</code>: Block und gerichteter Pfeil von <code>CanNm.c</code> entfernt.\n</li><li>Header-Inklusion <code>MemMap.h</code>: Ersetzt durch modulspezifischen Header <code>CanNm_MemMap.h</code> (gerichteter Pfeil von <code>CanNm.c</code>).\n</li></ul>"}]};
